-- lua/plugins/java.lua
return {
  {
    "mfussenegger/nvim-jdtls",
    -- generated by claude
    -- don't put metadata into my git workdir
    -- disable test feature, rely on neotest-java
    -- src: https://github.com/eclipse-jdtls/eclipse.jdt.ls/issues/3367
    opts = function(_, opts)
      opts.test = false

      opts.full_cmd = function(o)
        local fname = vim.api.nvim_buf_get_name(0)
        local root_dir = o.root_dir(fname)
        local project_name = o.project_name(root_dir)
        local cmd = vim.deepcopy(o.cmd)
        if project_name then
          vim.list_extend(cmd, {
            "--jvm-arg=-Djava.import.generatesMetadataFilesAtProjectRoot=false",
            "-configuration",
            o.jdtls_config_dir(project_name),
            "-data",
            o.jdtls_workspace_dir(project_name),
          })
        end
        return cmd
      end
    end,
  },
}
